// linkParents points ci's columns for its nested ancestors at their rows,
// found in known (rows a Batch is creating, by name) or else looked up by
// name: a nested resource's row is keyed by a surrogate of its own, not by
// its id.
func (r *GraphQLRateRepository) linkParents(ctx context.Context, ci *resourceql.CreateInput, name string, known map[string]string) error {
	ids, err := repox.SplitName(name, "hotels", "ratePlans", "rates")
	if err != nil {
		return err
	}
	{
		n := "hotels/" + ids[0] + "/ratePlans/" + ids[1]
		if k, ok := known[n]; ok {
			ci.RatePlanId = k
		} else if k, found, err := rateplanResourceKey(ctx, r.Svc, n); err != nil {
			return err
		} else if found {
			ci.RatePlanId = k
		}
	}
	return nil
}

// Get returns the record addressed by its resource name.
func (r *GraphQLRateRepository) Get(ctx context.Context, name string) (*ratev1.Rate, error) {
	row, err := r.find(ctx, name)
	if err != nil {
		return nil, err
	}
	return r.toProto(ctx, row, nil)
}

// rowID returns the surrogate key of the row named name, looked up by name:
// the id is unique only under the parent, so it is not the key.
// repox.ErrNotFound when there is no such row.
func (r *GraphQLRateRepository) rowID(ctx context.Context, name string) (string, error) {
	row, err := r.find(ctx, name)
	if err != nil {
		return "", err
	}
	return row.Id, nil
}

// find reads the row named name; repox.ErrNotFound when there is none.
func (r *GraphQLRateRepository) find(ctx context.Context, name string) (*resourceql.RateResource, error) {
	if _, err := repox.SplitName(name, "hotels", "ratePlans", "rates"); err != nil {
		return nil, err
	}
	row, err := r.Svc.Query.Rate.Resource.Find(ctx, resourceql.List().Where(resourceql.Name.Eq(name)))
	if err != nil {
		return nil, mapGraphQLErr(err)
	}
	if row == nil {
		return nil, repox.ErrNotFound
	}
	return row, nil
}

// get loads by surrogate key — the private read every generated method
// re-reads through.
func (r *GraphQLRateRepository) get(ctx context.Context, id string) (*ratev1.Rate, error) {
	row, err := r.Svc.Query.Rate.Resource.Get(ctx, id)
	if err != nil {
		return nil, mapGraphQLErr(err)
	}
	if row == nil {
		return nil, repox.ErrNotFound
	}
	return r.toProto(ctx, row, nil)
}

