// List returns one page of records under parent.
func (r *GraphQLRateRepository) List(ctx context.Context, parent string, in repox.ListInput) ([]*ratev1.Rate, string, error) {
	parentIDs, err := repox.SplitName(parent, "hotels", "ratePlans")
	if err != nil {
		return nil, "", err
	}
	// AIP-159: "-" for the parent reads across every parent.
	if parentIDs[len(parentIDs)-1] == "-" {
		return r.list(ctx, in)
	}
	// The parent is nested, so its row is found by name.
	keys, err := rateplanResourceKeys(ctx, r.Svc, parent)
	if err != nil {
		return nil, "", err
	}
	return r.list(ctx, in, resourceql.RatePlanId.In(keys...))
}

func (r *GraphQLRateRepository) list(ctx context.Context, in repox.ListInput, scope ...graphql.Predicate) ([]*ratev1.Rate, string, error) {
	if !in.ShowDeleted {
		scope = append(scope, resourceql.DeleteTime.IsNull(true))
	}
	conds, err := filterx.Parse(in.Filter)
	if err != nil {
		return nil, "", repox.MapFilterxErr(err)
	}
	conds = append(conds, in.Where...)
	if err := repox.CheckReadMask((*ratev1.Rate)(nil), in.ReadMask); err != nil {
		return nil, "", err
	}
	eng := filterx.Hasura[resourceql.RateResource](rate.RateFilterSpec, r.Svc.Query.Rate.Resource).Scope(scope...)
	for f, h := range r.ListOverrides {
		eng.Override(f, h)
	}
	rows, next, err := eng.List(ctx, filterx.ListInput{
		PageSize:  in.PageSize,
		PageToken: in.PageToken,
		OrderBy:   in.OrderBy,
		Filter:    conds,
	})
	if err != nil {
		return nil, "", repox.MapFilterxErr(err)
	}
	items := make([]*ratev1.Rate, 0, len(rows))
	for i := range rows {
		out, err := r.toProto(ctx, &rows[i], in.ReadMask)
		if err != nil {
			return nil, "", err
		}
		repox.Narrow(out, in.ReadMask)
		items = append(items, out)
	}
	return items, next, nil
}

// Update persists the masked fields of in; an empty mask replaces every
// mutable field. When in.Etag is set the write is guarded server-side
// (UpdateIfMatch); a stale etag returns repox.ErrConflict.
func (r *GraphQLRateRepository) Update(ctx context.Context, in *ratev1.Rate, paths []string) (*ratev1.Rate, error) {
	return r.update(ctx, in, paths, nil)
}

// UpdateWithOutputOnly is Update plus the server-owned fields outputPaths
// names, in the same patch and under the same guard.
func (r *GraphQLRateRepository) UpdateWithOutputOnly(ctx context.Context, in *ratev1.Rate, paths, outputPaths []string) (*ratev1.Rate, error) {
	return r.update(ctx, in, paths, outputPaths)
}

